import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';import 'chat_screen.dart';class ChatInboxScreen extends StatelessWidget{const ChatInboxScreen({super.key});@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser!.uid;return StreamBuilder<QuerySnapshot>(stream:FirebaseFirestore.instance.collection('chats').where('participants',arrayContains:u).orderBy('lastMessageAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Belum ada percakapan.'));return ListView(children:s.data!.docs.map((d){final x=d.data() as Map<String,dynamic>;final o=(x['participants'] as List).firstWhere((v)=>v!=u,orElse:()=>u).toString();return ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(x['productTitle']??'Chat'),subtitle:Text(x['lastMessage']??''),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatScreen(sellerId:o,sellerName:'Pengguna Flowa',productId:x['productId']??'',productTitle:x['productTitle']??''))));}).toList());});}}